import { createServer } from 'node:http'
import { ProxyAgent, request } from './index.js'

let connections = 0
// A plain node:http server: it has no 'connect' listener, so undici's CONNECT
// tunnel request gets the socket closed under it => UND_ERR_SOCKET.
const server = createServer((req, res) => res.end('nope')).listen(0)
server.on('connection', () => {
  connections++
  if (connections > 20) {
    console.log('LOOPING: connections =', connections)
    process.exit(1)
  }
})
await new Promise(resolve => server.once('listening', resolve))
const port = server.address().port

const agent = new ProxyAgent(`http://localhost:${port}`)
try {
  const res = await request('http://example.com', { dispatcher: agent })
  console.log('unexpected success', res.statusCode, await res.body.text())
} catch (err) {
  console.log('rejected as expected:', err.code, err.message)
}
console.log('connections =', connections)
await agent.close()
server.close()

