/**
 * Fail every request left in the queue. Only valid when nothing is running,
 * i.e. when no request can make progress on its own anymore.
 *
 * @param {Client} client
 * @param {Error} err
 * @returns {void}
 */
function errorQueuedRequests (client, err) {
  assert(client[kPendingIdx] === client[kRunningIdx])

  const requests = client[kQueue].splice(client[kRunningIdx])

  for (let i = 0; i < requests.length; i++) {
    const request = requests[i]
