import { ok } from 'node:assert'
import { createServer, request as httpRequest } from 'node:http'
import { request as httpsRequest } from 'node:https'
import { ProxyAgent, request } from './index.js'

// The reporter's proxy: absolute-form HTTP requests only, no CONNECT support.
const server = createServer((req, res) => {
  ok(req.url)
  const targetUrl = new URL(req.url)
  req.pipe(
    (targetUrl.protocol === 'https:' ? httpsRequest : httpRequest)({
      method: req.method,
      hostname: targetUrl.hostname,
      port: targetUrl.port,
      path: targetUrl.pathname + targetUrl.search,
      headers: req.headers
    }, (proxiedRes) => {
      ok(proxiedRes.statusCode)
      res.writeHead(proxiedRes.statusCode, proxiedRes.statusMessage, proxiedRes.headers)
      proxiedRes.pipe(res)
    }).once('error', res.destroy.bind(res))
  )
}).listen(0)
await new Promise(resolve => server.once('listening', resolve))
const port = server.address().port

const target = createServer((req, res) => res.end('hello from target')).listen(0)
await new Promise(resolve => target.once('listening', resolve))
const targetPort = target.address().port

const agent = new ProxyAgent({ uri: `http://localhost:${port}`, proxyTunnel: false })
const res = await request(`http://localhost:${targetPort}/`, { dispatcher: agent })
console.log('proxyTunnel:false =>', res.statusCode, await res.body.text())
await agent.close()
server.close()
target.close()

